action.code:
size_t nbits = binfo->nbits;
size_t lg_group = binfo->lg_group;
size_t ngroups = binfo->ngroups;

size_t group = min_bit >> lg_group;
size_t bit = min_bit & ((static_cast<bitmap_t>(1) << lg_group) - 1);

for (size_t g = group; g < ngroups; ++g) {
    bitmap_t word = bitmap[g];
    if (g == group && bit != 0) {
        bitmap_t mask = (static_cast<bitmap_t>(1) << bit) - 1;
        word |= mask; // ignore bits before min_bit
    }
    bitmap_t inv = ~word;
    if (inv != 0) {
        size_t i = std::countr_zero(inv);
        size_t idx = (g << lg_group) + i;
        return (idx < nbits) ? idx : nbits;
    }
}
return nbits;

